            [
                'name' => 'renew',
                'purpose' => 'extend an active lease owned by the same actor',
                'writes_events' => true,
                'writes_projection' => true,
            ],
            [
                'name' => 'release',
                'purpose' => 'release an active reservation and free the packet for future claim',
                'writes_events' => true,
                'writes_projection' => true,
