    public function continuationToken(array $options = []): array
    {
        $digest = $this->readinessDigest($options);
        $manifest = $this->integrityManifest($options);

        $token = [
            'id' => 'CONTINUATION-TOKEN-SELF-CONSTRUCTION-PHASE-5',
