     */
    private function hasHotScope(array $paths): bool
    {
        foreach ($paths as $path) {
            if (str_starts_with($path, 'runtimes/python/voice_realtime/')
                || $path === 'runtimes/python/voice_realtime/**'
                || str_starts_with($path, 'app/Services/Ai/Voice/')
                || $path === 'app/Services/Ai/Voice/**'
                || $path === 'app/Services/Ai/Kernel/Architecture/KernelArchitectureStaticScanner.php'
                || $path === 'docs/engineering-knowledge-base/atlas-ai-voice-realtime-surface.md') {
                return true;
            }
        }

        return false;
    }

    /**
     * @param  array{workspace?: string|null, target?: string|null, packet?: string|null}  $options
     * @return array<string, mixed>|null
     */
    private function selectedSplitPacket(array $options): ?array
    {
        $packetId = $options['packet'] ?? null;
        if ($packetId === null || $packetId === '') {
            return null;
        }

        $splitter = $this->workSplitter([
            'workspace' => $options['workspace'] ?? null,
            'target' => $options['target'] ?? null,
        ]);

        $packet = collect((array) data_get($splitter, 'split.packets', []))->firstWhere('packet_id', $packetId);

        return is_array($packet) ? $packet : null;
    }

    private function packetCommand(string $option, mixed $packetId): string
    {
        $command = 'php artisan atlas:ai:self-construction --'.$option;

        if (is_string($packetId) && $packetId !== '') {
            $command .= ' --packet='.$packetId;
        }

        return $command.' --json';
    }

    /**
     * @param  array{actor?: string|null}  $options
     */
    private function reservationActor(array $options): string
    {
        $actor = trim((string) ($options['actor'] ?? 'codex'));

        return $actor === '' ? 'codex' : $actor;
    }

    /**
     * @param  array{session?: string|null}  $options
     */
    private function reservationSession(array $options): string
    {
        $session = trim((string) ($options['session'] ?? 'local-session'));

        return $session === '' ? 'local-session' : $session;
    }

    /**
     * @return array{provider: string, role: string, receives: string, best_for: list<string>}
     */
    private function providerRoleForActor(string $actor): array
    {
        $normalized = strtolower(trim($actor));

        if (str_starts_with($normalized, 'claude')) {
            return [
                'provider' => 'claude',
                'role' => 'planner_or_reviewer',
                'receives' => 'architecture_and_acceptance_packet',
                'best_for' => ['architecture_review', 'acceptance_criteria', 'critique', 'integration_review'],
            ];
        }

        if (str_starts_with($normalized, 'gemini')) {
            return [
                'provider' => 'gemini',
                'role' => 'scout_or_long_context_mapper',
                'receives' => 'source_map_and_research_packet',
                'best_for' => ['long_context_mapping', 'source_inventory', 'research_synthesis', 'cross_file_scan'],
            ];
        }

        if (str_starts_with($normalized, 'local')) {
            return [
                'provider' => 'local_runtime',
                'role' => 'deterministic_gate_runner',
                'receives' => 'commands_and_expected_outputs',
                'best_for' => ['test_execution', 'linting', 'docs_health', 'architecture_validation'],
            ];
        }

        return [
            'provider' => str_starts_with($normalized, 'codex') ? 'codex' : 'generic_ai_agent',
            'role' => 'implementation_worker',
            'receives' => 'packet_scope_bootstrap',
            'best_for' => ['scoped_implementation', 'tests', 'docs_updates', 'evidence_reporting'],
        ];
    }

    private function agentControlPlaneRuntimeSchemaReady(): bool
    {
        return \Illuminate\Support\Facades\Schema::hasTable('atlas_self_construction_agent_runs')
            && \Illuminate\Support\Facades\Schema::hasTable('atlas_self_construction_agent_heartbeats');
    }

    /**
     * @param  array<string, mixed>  $reservation
     * @return array<string, mixed>
     */
    private function syncAgentRunFromReservation(array $reservation): array
    {
        $actor = (string) data_get($reservation, 'actor');
        $providerRole = $this->providerRoleForActor($actor);
        $state = (string) data_get($reservation, 'state', 'claimed');
        $status = match ($state) {
            'completed' => 'succeeded',
            'released' => 'cancelled',
            default => 'running',
        };
        $leaseExpiresAt = (string) data_get($reservation, 'lease_expires_at');
        $expiresAt = strtotime($leaseExpiresAt);
        $liveness = match (true) {
            $status === 'succeeded' => 'completed',
            $status === 'cancelled' => 'released',
            $expiresAt !== false && $expiresAt > time() => 'active_lease',
            $expiresAt !== false => 'expired_lease',
            default => 'unknown',
        };
        $reservationId = (string) data_get($reservation, 'reservation_id');
        $packetId = (string) data_get($reservation, 'packet_id');
        $runKey = 'SELF-CONSTRUCTION-RUN-'.strtoupper(substr(hash('sha256', $reservationId.'|'.$packetId), 0, 24));

        $run = \App\Models\AtlasSelfConstructionAgentRun::query()->updateOrCreate(
            ['run_key' => $runKey],
            [
                'packet_id' => $packetId,
                'reservation_id' => $reservationId,
                'actor' => $actor,
                'provider' => (string) data_get($providerRole, 'provider', 'generic_ai_agent'),
                'provider_role' => (string) data_get($providerRole, 'role', 'implementation_worker'),
                'session_id' => (string) data_get($reservation, 'session'),
                'workspace_id' => 'FORGE-WORKSPACE-ATLAS-SELF-CONSTRUCTION-0001',
                'obra_id' => 'OBRA-ATLAS-SELF-CONSTRUCTION-OS',
                'status' => $status,
                'liveness' => $liveness,
                'packet_hash' => data_get($reservation, 'packet_hash'),
                'allowed_files_hash' => data_get($reservation, 'allowed_files_hash'),
                'lease_expires_at' => data_get($reservation, 'lease_expires_at'),
                'started_at' => data_get($reservation, 'claimed_at'),
                'finished_at' => data_get($reservation, 'completed_at') ?: data_get($reservation, 'released_at'),
                'completion_evidence_hash' => data_get($reservation, 'completion_evidence_hash'),
                'summary' => $status === 'succeeded'
                    ? 'Self-Construction packet completed from reservation ledger.'
                    : 'Self-Construction packet active from reservation ledger.',
                'metadata' => [
                    'source' => 'self_construction_reservation_ledger',
                    'reservation_state' => $state,
                    'release_reason' => data_get($reservation, 'release_reason'),
                    'completion_reason' => data_get($reservation, 'completion_reason'),
                ],
            ],
        );

        return [
            'run_id' => $run->id,
            'run_key' => $run->run_key,
            'packet_id' => $run->packet_id,
            'reservation_id' => $run->reservation_id,
            'actor' => $run->actor,
            'provider' => $run->provider,
            'session' => $run->session_id,
            'status' => $run->status,
            'liveness' => $run->liveness,
            'created' => $run->wasRecentlyCreated,
        ];
    }

    private function recommendedProviderForLane(string $lane): string
    {
        return match ($lane) {
            'docs', 'packet_contracts' => 'claude',
            'research', 'source_mapping', 'long_context' => 'gemini',
            'gates', 'validation' => 'local',
            default => 'codex',
        };
    }

    /**
     * @return list<string>
     */
    private function changedFiles(): array
    {
        $root = base_path();
        $commands = [
            'git -C '.escapeshellarg($root).' diff --name-only',
            'git -C '.escapeshellarg($root).' ls-files --others --exclude-standard',
        ];

        $files = [];
        foreach ($commands as $command) {
            $output = shell_exec($command);
            foreach (explode("\n", trim((string) $output)) as $line) {
                $path = trim($line);
                if ($path !== '') {
                    $files[] = $path;
                }
            }
        }

        return array_values(array_unique($files));
    }

    /**
     * @param  list<string>  $allowed
     * @param  list<string>  $forbidden
     */
    private function classifyPath(string $path, array $allowed, array $forbidden): string
    {
        foreach ($forbidden as $pattern) {
            if ($this->pathMatches($path, $pattern)) {
                return str_contains($pattern, 'voice') || str_contains($pattern, 'Kernel') ? 'hot_external' : 'forbidden';
            }
        }

        foreach ($allowed as $pattern) {
            if ($this->pathMatches($path, $pattern)) {
                return 'allowed';
            }
        }

        return 'unknown';
    }

    private function pathMatches(string $path, string $pattern): bool
    {
        if ($path === $pattern) {
            return true;
        }

        if (str_ends_with($pattern, '/**')) {
            return str_starts_with($path, substr($pattern, 0, -3).'/');
        }

        return false;
    }

    /**
     * @return array{path: string, exists: bool, line_count: int|null}
     */
    private function docStatus(string $path): array
    {
        $absolutePath = base_path($path);

        return [
            'path' => $path,
            'exists' => is_file($absolutePath),
            'line_count' => is_file($absolutePath) ? count(file($absolutePath, FILE_IGNORE_NEW_LINES)) : null,
        ];
    }

    private function docContent(string $path): string
    {
        $absolutePath = base_path($path);

        return is_file($absolutePath) ? (string) file_get_contents($absolutePath) : '';
    }

    /**
     * @param  array<string, mixed>  $payload
     */
    private function stableHash(array $payload): string
    {
        ksort($payload);

        return hash('sha256', (string) json_encode($payload, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE));
    }
}
